[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
/* === RESET & BASE === */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{font-size:16px;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#F5F7FA;color:#0D1421;line-height:1.5;min-height:100vh}
a{color:#3861FB;text-decoration:none}
a:hover{text-decoration:underline}
button{cursor:pointer;font-family:inherit}

/* === TOP METRICS BAR === */
.top-metrics{background:#fff;border-bottom:1px solid #EFF2F5;padding:12px 0}
.top-metrics-inner{max-width:1400px;margin:0 auto;padding:0 24px;display:flex;align-items:center;gap:32px;overflow-x:auto}
.metric-item{display:flex;align-items:center;gap:8px;white-space:nowrap;flex-shrink:0}
.metric-label{font-size:12px;font-weight:500;color:#808A9D;text-transform:uppercase;letter-spacing:0.5px}
.metric-value{font-size:14px;font-weight:700;color:#0D1421}
.metric-change{font-size:12px;font-weight:600;padding:2px 6px;border-radius:4px}
.metric-change.up{color:#16c784;background:#E6F9F2}
.metric-change.down{color:#ea3943;background:#FDEAEC}
.metric-divider{width:1px;height:24px;background:#EFF2F5;flex-shrink:0}
.fear-greed-indicator{display:flex;align-items:center;gap:8px}
.fg-score{font-size:14px;font-weight:700;color:#0D1421}
.fg-label{font-size:12px;font-weight:500;color:#808A9D;padding:2px 8px;background:#F5F7FA;border-radius:4px}

/* === HEADER / NAV === */
.header{background:#fff;border-bottom:1px solid #EFF2F5;position:sticky;top:0;z-index:100}
.header-inner{max-width:1400px;margin:0 auto;padding:0 24px;display:flex;align-items:center;height:56px;gap:24px}
.logo{display:flex;align-items:center;gap:8px;font-size:18px;font-weight:700;color:#0D1421;flex-shrink:0}
.logo-icon{width:32px;height:32px;background:#3861FB;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:16px;font-weight:700}
.main-nav{display:flex;align-items:center;gap:4px;flex:1}
.nav-item{position:relative;padding:8px 14px;font-size:14px;font-weight:500;color:#0D1421;border-radius:8px;transition:background .15s;cursor:pointer;white-space:nowrap}
.nav-item:hover{background:#F5F7FA;text-decoration:none}
.nav-item.active{color:#3861FB;background:#EEF1FD}
.nav-cta{display:flex;align-items:center;gap:8px;flex-shrink:0}
.btn-login{font-size:14px;font-weight:500;color:#3861FB;padding:8px 16px;border-radius:8px;border:1px solid transparent;background:transparent;transition:background .15s}
.btn-login:hover{background:#EEF1FD}
.btn-signup{font-size:14px;font-weight:600;color:#fff;background:#3861FB;padding:8px 20px;border-radius:8px;border:none;transition:background .15s}
.btn-signup:hover{background:#2B4FD6}

/* === PROMO BANNER === */
.promo-banner{background:linear-gradient(135deg,#3861FB 0%,#5B4FCF 100%);color:#fff;position:relative;overflow:hidden}
.promo-inner{max-width:1400px;margin:0 auto;padding:12px 24px;display:flex;align-items:center;justify-content:center;gap:12px;min-height:44px}
.promo-text{font-size:14px;font-weight:500;text-align:center}
.promo-cta{font-size:13px;font-weight:600;color:#fff;background:rgba(255,255,255,0.2);padding:6px 16px;border-radius:6px;border:none;white-space:nowrap;transition:background .15s}
.promo-cta:hover{background:rgba(255,255,255,0.3)}
.promo-arrow{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.15);border:none;color:#fff;width:28px;height:28px;border-radius:50%;font-size:14px;display:flex;align-items:center;justify-content:center;transition:background .15s}
.promo-arrow:hover{background:rgba(255,255,255,0.25)}
.promo-arrow.prev{left:16px}
.promo-arrow.next{right:16px}
.promo-dots{display:flex;gap:6px;align-items:center}
.promo-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.4);border:none;padding:0;transition:background .15s}
.promo-dot.active{background:#fff}

/* === AI ALERTS BAR === */
.ai-bar{background:#fff;border-bottom:1px solid #EFF2F5}
.ai-bar-inner{max-width:1400px;margin:0 auto;padding:10px 24px;display:flex;align-items:center;gap:16px;overflow-x:auto}
.ai-prompt{display:flex;align-items:center;gap:10px;background:#F8FAFC;border:1px solid #EFF2F5;border-radius:8px;padding:8px 16px;font-size:13px;color:#0D1421;cursor:pointer;white-space:nowrap;transition:background .15s;flex-shrink:0}
.ai-prompt:hover{background:#EEF1FD;border-color:#3861FB}
.ai-prompt-icon{font-size:16px}
.ai-quick-asks{display:flex;gap:8px;overflow-x:auto;flex:1}
.ai-quick-ask{font-size:12px;font-weight:500;color:#808A9D;padding:6px 12px;border:1px solid #EFF2F5;border-radius:20px;background:#fff;white-space:nowrap;cursor:pointer;transition:all .15s;flex-shrink:0}
.ai-quick-ask:hover{color:#3861FB;border-color:#3861FB;background:#EEF1FD}

/* === MAIN CONTENT === */
.main-content{max-width:1400px;margin:0 auto;padding:24px}

/* === CATEGORY TABS === */
.category-tabs{display:flex;gap:4px;margin-bottom:16px;flex-wrap:wrap}
.cat-tab{padding:8px 16px;font-size:13px;font-weight:500;color:#808A9D;border:none;background:transparent;border-radius:8px;transition:all .15s}
.cat-tab:hover{color:#0D1421;background:#F5F7FA}
.cat-tab.active{color:#3861FB;background:#EEF1FD;font-weight:600}

/* === NETWORK FILTER TABS === */
.network-tabs{display:flex;gap:4px;margin-bottom:20px;flex-wrap:wrap}
.net-tab{padding:6px 14px;font-size:12px;font-weight:500;color:#808A9D;border:1px solid #EFF2F5;background:#fff;border-radius:20px;transition:all .15s}
.net-tab:hover{color:#0D1421;border-color:#CBD5E1}
.net-tab.active{color:#3861FB;border-color:#3861FB;background:#EEF1FD;font-weight:600}

/* === TABLE CONTROLS === */
.table-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:12px}
.controls-left{display:flex;align-items:center;gap:8px}
.controls-right{display:flex;align-items:center;gap:8px}
.ctrl-btn{padding:8px 16px;font-size:13px;font-weight:500;color:#0D1421;border:1px solid #EFF2F5;background:#fff;border-radius:8px;display:flex;align-items:center;gap:6px;transition:all .15s}
.ctrl-btn:hover{border-color:#CBD5E1;background:#F8FAFC}
.ctrl-btn.active{color:#3861FB;border-color:#3861FB;background:#EEF1FD}
.ctrl-btn .arrow{font-size:10px;margin-left:2px}

/* === DROPDOWNS === */
.dropdown-panel{background:#fff;border:1px solid #EFF2F5;border-radius:12px;padding:16px;margin-bottom:16px;box-shadow:0 4px 24px rgba(0,0,0,0.08);display:none}
.dropdown-panel.open{display:block}
.dropdown-panel h4{font-size:13px;font-weight:600;color:#0D1421;margin-bottom:12px}
.column-toggles{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
.col-toggle{display:flex;align-items:center;gap:8px;font-size:13px;color:#0D1421;cursor:pointer}
.col-toggle input[type="checkbox"]{accent-color:#3861FB;width:16px;height:16px}
.filter-row{display:flex;gap:16px;flex-wrap:wrap;align-items:flex-end}
.filter-group{display:flex;flex-direction:column;gap:4px}
.filter-group label{font-size:11px;font-weight:600;color:#808A9D;text-transform:uppercase;letter-spacing:0.5px}
.filter-group input,.filter-group select{padding:8px 12px;font-size:13px;border:1px solid #EFF2F5;border-radius:8px;font-family:inherit;color:#0D1421;background:#fff}
.filter-group input:focus,.filter-group select:focus{outline:none;border-color:#3861FB;box-shadow:0 0 0 3px rgba(56,97,251,0.1)}
.filter-actions{display:flex;gap:8px;align-items:flex-end}
.btn-apply{font-size:13px;font-weight:600;color:#fff;background:#3861FB;padding:8px 20px;border-radius:8px;border:none}
.btn-apply:hover{background:#2B4FD6}
.btn-reset{font-size:13px;font-weight:500;color:#808A9D;background:#F5F7FA;padding:8px 16px;border-radius:8px;border:none}
.btn-reset:hover{background:#EFF2F5}

/* === INDEX TRACKER ROW === */
.index-tracker{background:#F8FAFC;border:1px solid #EFF2F5;border-radius:10px;padding:12px 16px;margin-bottom:16px;display:flex;align-items:center;gap:24px;flex-wrap:wrap}
.index-name{font-size:13px;font-weight:600;color:#0D1421}
.index-symbol{font-size:11px;color:#808A9D}
.index-price{font-size:16px;font-weight:700;color:#0D1421}
.index-changes{display:flex;gap:12px}
.index-chg{font-size:12px;font-weight:600;padding:2px 6px;border-radius:4px}
.index-chg.up{color:#16c784;background:#E6F9F2}
.index-chg.down{color:#ea3943;background:#FDEAEC}

/* === CRYPTO TABLE === */
.table-container{background:#fff;border:1px solid #EFF2F5;border-radius:12px;overflow:hidden}
.table-wrapper{overflow-x:auto}
table.crypto-table{width:100%;border-collapse:collapse;font-size:13px}
.crypto-table thead th{text-align:right;padding:12px 16px;font-size:12px;font-weight:600;color:#808A9D;text-transform:uppercase;letter-spacing:0.3px;border-bottom:2px solid #EFF2F5;white-space:nowrap;background:#FAFBFC;cursor:pointer;user-select:none;transition:color .15s}
.crypto-table thead th:hover{color:#0D1421}
.crypto-table thead th:first-child{text-align:center}
.crypto-table thead th:nth-child(2){text-align:left}
.crypto-table thead th .sort-arrow{font-size:10px;margin-left:2px;opacity:0.4}
.crypto-table thead th.sorted .sort-arrow{opacity:1;color:#3861FB}
.crypto-table tbody td{text-align:right;padding:12px 16px;border-bottom:1px solid #F5F7FA;white-space:nowrap;font-variant-numeric:tabular-nums}
.crypto-table tbody td:first-child{text-align:center;color:#808A9D;font-size:12px}
.crypto-table tbody td:nth-child(2){text-align:left}
.crypto-table tbody tr{cursor:pointer;transition:background .1s}
.crypto-table tbody tr:hover{background:#F8FAFC}
.crypto-table tbody tr.index-row{background:#F8FAFC}
.crypto-table tbody tr.index-row td{border-bottom:1px solid #EFF2F5}
.coin-cell{display:flex;align-items:center;gap:10px}
.coin-icon{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0}
.coin-info{display:flex;flex-direction:column}
.coin-name{font-weight:600;color:#0D1421;font-size:13px}
.coin-symbol{font-size:11px;color:#808A9D}
.price-cell{font-weight:600;color:#0D1421}
.chg-up{color:#16c784}
.chg-down{color:#ea3943}
.chg-neutral{color:#808A9D}
.supply-cell{color:#0D1421}
.mcap-cell{font-weight:500}

/* sparkline */
.sparkline-cell{text-align:right;padding:12px 16px}
.sparkline-svg{display:inline-block;vertical-align:middle}

/* === PAGINATION === */
.pagination-bar{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-top:1px solid #EFF2F5;flex-wrap:wrap;gap:12px}
.showing-text{font-size:12px;color:#808A9D}
.pagination-pages{display:flex;align-items:center;gap:4px}
.page-btn{min-width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:500;color:#0D1421;border:1px solid #EFF2F5;background:#fff;border-radius:8px;padding:0 10px;transition:all .15s}
.page-btn:hover{border-color:#CBD5E1;background:#F8FAFC}
.page-btn.active{color:#fff;background:#3861FB;border-color:#3861FB}
.page-btn.disabled{opacity:0.3;pointer-events:none}
.page-ellipsis{font-size:13px;color:#808A9D;padding:0 4px}

/* === MARKET SUMMARY === */
.market-summary{background:#fff;border:1px solid #EFF2F5;border-radius:12px;padding:24px;margin-top:32px}
.market-summary h2{font-size:20px;font-weight:700;margin-bottom:16px;color:#0D1421}
.market-summary p{font-size:14px;line-height:1.7;color:#4A5568;margin-bottom:12px}
.market-summary .highlight{font-weight:600;color:#0D1421}
.read-more-btn{font-size:14px;font-weight:600;color:#3861FB;background:none;border:none;padding:0;display:inline-flex;align-items:center;gap:4px;margin-top:4px}
.read-more-btn:hover{text-decoration:underline}
.expanded-content{display:none;margin-top:12px;padding-top:16px;border-top:1px solid #EFF2F5}
.expanded-content.open{display:block}
.market-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:16px}
.market-card{background:#F8FAFC;border-radius:10px;padding:16px}
.market-card-label{font-size:11px;font-weight:600;color:#808A9D;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px}
.market-card-value{font-size:18px;font-weight:700;color:#0D1421}
.market-card-change{font-size:12px;font-weight:600;margin-top:2px}

/* === INFO CONTENT === */
.info-content{background:#fff;border:1px solid #EFF2F5;border-radius:12px;padding:32px;margin-top:32px}
.info-content h2{font-size:18px;font-weight:700;margin-bottom:12px;color:#0D1421}
.info-content h3{font-size:16px;font-weight:600;margin:20px 0 8px;color:#0D1421}
.info-content p{font-size:14px;line-height:1.7;color:#4A5568;margin-bottom:12px}

/* === FOOTER === */
.footer{background:#fff;border-top:1px solid #EFF2F5;margin-top:32px;padding:40px 0 24px}
.footer-inner{max-width:1400px;margin:0 auto;padding:0 24px;display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:32px}
.footer-col h4{font-size:13px;font-weight:700;color:#0D1421;margin-bottom:12px;text-transform:uppercase;letter-spacing:0.5px}
.footer-col ul{list-style:none}
.footer-col li{margin-bottom:8px}
.footer-col a{font-size:13px;color:#808A9D;transition:color .15s}
.footer-col a:hover{color:#3861FB;text-decoration:none}
.footer-bottom{max-width:1400px;margin:0 auto;padding:24px;border-top:1px solid #F5F7FA;margin-top:24px;text-align:center;font-size:12px;color:#808A9D}

/* === RESPONSIVE === */
@media (max-width:768px){
  .main-nav{display:none}
  .top-metrics-inner{gap:16px}
  .table-wrapper{font-size:12px}
  .header-inner{padding:0 16px}
  .main-content{padding:16px}
  .promo-arrow{display:none}
  .filter-row{flex-direction:column}
  .category-tabs{overflow-x:auto;flex-wrap:nowrap}
  .network-tabs{overflow-x:auto;flex-wrap:nowrap}
}

@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
.animate-in{animation:fadeIn .2s ease-out}
</style>
</head>
<body>

<!-- TOP METRICS BAR -->
<div class="top-metrics">
  <div class="top-metrics-inner">
    <div class="metric-item">
      <span class="metric-label">Market Cap</span>
      <span class="metric-value">$2.56T</span>
      <span class="metric-change up">▲ 1.46%</span>
    </div>
    <div class="metric-divider"></div>
    <div class="metric-item">
      <span class="metric-label">CTP20 Index</span>
      <span class="metric-value">$155.36</span>
