      <span class="metric-label">Fear & Greed</span>
      <span class="fg-score">57</span>
      <span class="fg-label">Neutral</span>
    </div>
    <div class="metric-divider"></div>
    <div class="metric-item">
      <span class="metric-label">Altcoin Season</span>
      <span class="metric-value">37/100</span>
      <span class="fg-label">Bitcoin season</span>
    </div>
  </div>
</div>

<!-- HEADER / NAV -->
<header class="header">
  <div class="header-inner">
    <div class="logo">
      <div class="logo-icon">CT</div>
      CoinTracker Pro
    </div>
    <nav class="main-nav">
      <a class="nav-item active" href="#" data-nav="crypto">Cryptocurrencies</a>
      <a class="nav-item" href="#" data-nav="dashboards">Dashboards</a>
