    <span class="promo-text" id="promoText">CTP Launch: Secure $GENIUS Airdrop — Join Now</span>
    <button class="promo-cta" id="promoCta">Learn More</button>
    <button class="promo-arrow next" onclick="movePromo(1)" aria-label="Next banner">&#10095;</button>
  </div>
  <div style="display:flex;justify-content:center;gap:6px;padding-bottom:10px" id="promoDots"></div>
</div>

<!-- AI ALERTS BAR -->
<div class="ai-bar">
  <div class="ai-bar-inner">
    <div class="ai-prompt">
      <span class="ai-prompt-icon">&#9889;</span>
      Stablecoin issuer eyes Solana DeFi expansion &#128064;
    </div>
    <div class="ai-quick-asks">
      <button class="ai-quick-ask">Why is the market up today?</button>
