  <div class="network-tabs" id="networkTabs">
    <button class="net-tab active" data-net="all">All Networks</button>
    <button class="net-tab" data-net="bsc">BSC</button>
    <button class="net-tab" data-net="solana">Solana</button>
    <button class="net-tab" data-net="base">Base</button>
    <button class="net-tab" data-net="ethereum">Ethereum</button>
    <button class="net-tab" data-net="more">More</button>
  </div>

  <!-- TABLE CONTROLS -->
  <div class="table-controls">
    <div class="controls-left">
      <button class="ctrl-btn">Market Cap <span class="arrow">&#9660;</span></button>
      <button class="ctrl-btn">Volume(24h) <span class="arrow">&#9660;</span></button>
    </div>
    <div class="controls-right">
      <button class="ctrl-btn" id="btnColumns" onclick="togglePanel('columnsPanel')">Columns</button>
      <button class="ctrl-btn" id="btnFilters" onclick="togglePanel('filtersPanel')">Filters</button>
    </div>
  </div>

  <!-- COLUMNS PANEL -->
  <div class="dropdown-panel" id="columnsPanel">
    <h4>Toggle Columns</h4>
    <div class="column-toggles">
      <label class="col-toggle"><input type="checkbox" checked onchange="toggleColumn(2,this)"> Rank</label>
      <label class="col-toggle"><input type="checkbox" checked onchange="toggleColumn(3,this)"> Name</label>
