      <label class="col-toggle"><input type="checkbox" checked onchange="toggleColumn(10,this)"> Circulating Supply</label>
      <label class="col-toggle"><input type="checkbox" checked onchange="toggleColumn(11,this)"> Last 7 Days</label>
    </div>
  </div>

  <!-- FILTERS PANEL -->
  <div class="dropdown-panel" id="filtersPanel">
    <h4>Filter Cryptocurrencies</h4>
    <div class="filter-row">
      <div class="filter-group">
        <label>Price Range</label>
        <div style="display:flex;gap:8px">
