function fmtPrice(v){return v<0.01?'$'+v.toFixed(8):v<1?'$'+v.toFixed(4):v<1000?'$'+v.toFixed(2):'$'+v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
function fmtPct(v){return (v>=0?'+':'')+v.toFixed(2)+'%'}
function pctClass(v){return v>0?'chg-up':v<0?'chg-down':'chg-neutral'}
function coinColor(s){const colors={BTC:'#F7931A',ETH:'#627EEA',USDT:'#26A17B',XRP:'#23292F',BNB:'#F3BA2F',USDC:'#2775CA',SOL:'#9945FF',ADA:'#0033AD',AVAX:'#E84142',DOGE:'#C2A633',DOT:'#E6007A',LINK:'#2A5ADA',MATIC:'#8247E5',SHIB:'#FFA409',LTC:'#345D9D',UNI:'#FF007A',XLM:'#080000',ATOM:'#2E3148'};return colors[s]||'#'+Math.floor(Math.abs(Math.sin(s.charCodeAt(0)*100+ (s.charCodeAt(1)||0)*10))*16777215).toString(16).slice(0,6)}
function genSparkline(vals,isUp){const w=100,h=28,pad=2;const min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;let d='';vals.forEach((v,i)=>{const x=pad+(w-2*pad)*i/(vals.length-1);const y=h-1-pad-((v-min)/range)*(h-2*pad-2);d+=(i===0?'M':'L')+x.toFixed(1)+','+y.toFixed(1)});const color=isUp?'#16c784':'#ea3943';return'<svg class="sparkline-svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'"><path d="'+d+'" fill="none" stroke="'+color+'" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'}

// Sparkline data cache
const sparklineCache={};
cryptoData.forEach(coin=>{
  const vals=[];let v=coin.p*(0.85+Math.random()*0.3);
  for(let i=0;i<20;i++){v*=(1+(Math.random()-0.48)*0.05);vals.push(v)}
  sparklineCache[coin.s]=vals;
});

function renderTable(data,page,perPage){
  const start=(page-1)*perPage;
  const pageData=data.slice(start,start+perPage);
  const tbody=document.getElementById('tableBody');
  tbody.innerHTML=pageData.map((c,i)=>{
    const sl=sparklineCache[c.s];
    const lastVal=sl[sl.length-1],firstVal=sl[0];
    const spUp=lastVal>=firstVal;
    const r=start+i+1;
    return `<tr data-net="${c.net}" data-cat="${c.cat}">
      <td>${r}</td>
      <td><div class="coin-cell"><div class="coin-icon" style="background:${coinColor(c.s)}">${c.s.charAt(0)}</div><div class="coin-info"><span class="coin-name">${c.n}</span><span class="coin-symbol">${c.s}</span></div></div></td>
      <td class="price-cell">${fmtPrice(c.p)}</td>
      <td class="${pctClass(c.h1)}">${fmtPct(c.h1)}</td>
      <td class="${pctClass(c.h24)}">${fmtPct(c.h24)}</td>
      <td class="${pctClass(c.d7)}">${fmtPct(c.d7)}</td>
      <td class="mcap-cell">${c.mc}</td>
      <td>${c.vol}</td>
      <td class="supply-cell">${c.sup}</td>
      <td class="sparkline-cell">${genSparkline(sl,spUp)}</td>
    </tr>`;
  }).join('');
  document.getElementById('showingText').textContent=`Showing ${start+1}–${Math.min(start+perPage,data.length)} of ${data.length} assets`;
}

// Pagination
const PER_PAGE=100;
let currentPage=1;
let filteredData=[...cryptoData];
let activeCat='all';
let activeNet='all';

function renderPagination(total){
  const totalPages=Math.ceil(total/PER_PAGE);
  const container=document.getElementById('paginationPages');
  container.innerHTML='';
  const maxShow=7;
  let pages=[];
  if(totalPages<=maxShow){for(let i=1;i<=totalPages;i++)pages.push(i)}
  else{
    pages.push(1);
    if(currentPage>3)pages.push('...');
    for(let i=Math.max(2,currentPage-1);i<=Math.min(totalPages-1,currentPage+1);i++)pages.push(i);
    if(currentPage<totalPages-2)pages.push('...');
    pages.push(totalPages);
  }
  container.innerHTML=pages.map(p=>{
    if(p==='...')return'<span class="page-ellipsis">...</span>';
    return`<button class="page-btn${p===currentPage?' active':''}" onclick="goToPage(${p})">${p}</button>`;
  }).join('');
}

function goToPage(p){
  currentPage=p;
  renderTable(filteredData,currentPage,PER_PAGE);
  renderPagination(filteredData.length);
}

// Filtering
function applyFilters(){
  const cat=activeCat;
  const net=activeNet;
  filteredData=cryptoData.filter(c=>{
    if(cat!=='all'&&cat!=='more'&&c.cat!==cat)return false;
    if(net!=='all'&&net!=='more'&&c.net!==net)return false;
    const pmin=parseFloat(document.getElementById('filterPriceMin').value)||0;
    const pmax=parseFloat(document.getElementById('filterPriceMax').value)||Infinity;
    if(c.p<pmin||c.p>pmax)return false;
    const mcap=document.getElementById('filterMcap').value;
    if(mcap){
      const mcapNum=parseFloat(c.mc.replace(/[^0-9.]/g,''));
      const mult=c.mc.includes('T')?1e12:c.mc.includes('B')?1e9:c.mc.includes('M')?1e6:1;
      if(mcapNum*mult<parseFloat(mcap))return false;
    }
    const change=document.getElementById('filterChange').value;
    if(change==='up'&&c.h24<=0)return false;
    if(change==='down'&&c.h24>=0)return false;
    return true;
  });
  currentPage=1;
  renderTable(filteredData,currentPage,PER_PAGE);
  renderPagination(filteredData.length);
  document.getElementById('filtersPanel').classList.remove('open');
  document.getElementById('btnFilters').classList.remove('active');
}

function resetFilters(){
