});

// Network tabs
document.getElementById('networkTabs').addEventListener('click',function(e){
  if(!e.target.classList.contains('net-tab'))return;
  document.querySelectorAll('.net-tab').forEach(b=>b.classList.remove('active'));
  e.target.classList.add('active');
  activeNet=e.target.dataset.net;
  currentPage=1;
  filteredData=cryptoData.filter(c=>activeNet==='all'||activeNet==='more'||c.net===activeNet);
  if(activeCat!=='all'&&activeCat!=='more')filteredData=filteredData.filter(c=>c.cat===activeCat);
  renderTable(filteredData,currentPage,PER_PAGE);
  renderPagination(filteredData.length);
  document.getElementById('showingText').textContent=`Showing 1–${Math.min(PER_PAGE,filteredData.length)} of ${filteredData.length} assets`;
});

// Column toggle
function toggleColumn(colIdx,checkbox){
  const table=document.getElementById('cryptoTable');
  const rows=table.querySelectorAll('tr');
  rows.forEach(row=>{
    const cells=row.querySelectorAll('th,td');
    if(cells[colIdx])cells[colIdx].style.display=checkbox.checked?'':'none';
  });
}

// Panels toggle
function togglePanel(id){
  const panel=document.getElementById(id);
  const btnId=id==='columnsPanel'?'btnColumns':'btnFilters';
  const btn=document.getElementById(btnId);
  const otherId=id==='columnsPanel'?'filtersPanel':'columnsPanel';
  document.getElementById(otherId).classList.remove('open');
  const otherBtnId=otherId==='columnsPanel'?'btnColumns':'btnFilters';
  document.getElementById(otherBtnId).classList.remove('active');
  panel.classList.toggle('open');
  btn.classList.toggle('active');
}

// Market summary accordion
function toggleMarketSummary(){
  const content=document.getElementById('expandedSummary');
  const btn=document.getElementById('readMoreBtn');
  content.classList.toggle('open');
  btn.innerHTML=content.classList.contains('open')?'Read Less &#9650;':'Read More &#9660;';
}

// Promo carousel
const promos=[
  {text:'CTP Launch: Secure $GENIUS Airdrop — Join Now',cta:'Learn More'},
